import calendar

def add_months(date_str, n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")

    try:
        year, month, day = map(int, date_str.split('-'))
    except (ValueError, AttributeError):
        raise ValueError("date_str must be a valid ISO date string")

    if not (1 <= year <= 9999 and 1 <= month <= 12 and 1 <= day <= 31):
        raise ValueError("date_str must be a valid date")

    try:
        calendar.date_fromtimestamp(calendar.timegm((year, month, day, 0, 0, 0)))
    except (ValueError, OverflowError):
        raise ValueError("date_str must be a valid date")

    year += n // 12
    month += n % 12
    while month > 12:
        month -= 12
        year += 1
    while month < 1:
        month += 12
        year -= 1

    if month > 12 or month < 1 or year < 1 or year > 9999:
        raise ValueError("Result falls outside years 1..9999")

    max_day = calendar.monthrange(year, month)[1]
    day = min(day, max_day)

    return f"{year:04d}-{month:02d}-{day:02d}"
