def is_balanced(code):
    stack = []
    i = 0
    n = len(code)

    while i < n:
        c = code[i]

        if c == '"':
            # Skip the string literal
            i += 1
            while i < n and code[i] != '"':
                if code[i] == '\\':
                    i += 1 # Skip escaped character
                i += 1
            i += 1 # Skip closing quote
        elif c in '([{':
            stack.append(c)
        elif c in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if (top == '(' and c != ')') or (top == '[' and c != ']') or (top == '{' and c != '}'):
                return False
        i += 1

    return not stack
